    fn test_no_duplicates() {
        assert_eq!(remove_duplicates(vec![1, 2, 3]), vec![1, 2, 3]);
    }
    
    #[test]
    fn test_all_duplicates() {
        assert_eq!(remove_duplicates(vec![1, 1, 1]), vec![1]);
    }
    
    #[test]
    fn test_mixed_duplicates() {
        assert_eq!(remove_duplicates(vec![1, 2, 1, 3, 2, 4]), vec![1, 2, 3, 4]);
    }
    
    #[test]
    fn test_negative_numbers() {
        assert_eq!(remove_duplicates(vec![-1, 0, 1, -1, 2, 0]), vec![-1, 0, 1, 2]);
    }
    
    #[test]
    fn test_boundary_values() {
        assert_eq!(
            remove_duplicates(vec![i32::MIN, i32::MAX, i32::MIN, 0, i32::MAX]),
            vec![i32::MIN, i32::MAX, 0]
        );
    }
    
    #[test]
    fn test_preserves_order() {
        // The implementation preserves the order of first occurrence
        let input = vec![3, 1, 2, 3, 1, 4, 2];
        let output = remove_duplicates(input.clone());
        
        // Check no duplicates
        let unique: HashSet<_> = output.iter().collect();
        assert_eq!(unique.len(), output.len());
        
        // Check sets are equal
        let input_set: HashSet<_> = input.iter().collect();
        let output_set: HashSet<_> = output.iter().collect();
        assert_eq!(input_set, output_set);
    }
